SELECT a.hadm_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, COUNT(DISTINCT a.subject_id) AS patient_count, SUM(CASE WHEN l.itemid IN (17055, 17056, 17057) THEN 1 ELSE 0 END) AS ultrasound_count, AVG(CASE WHEN l.itemid IN (17055, 17056, 17057) THEN 1 ELSE 0 END) AS avg_ultrasound FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN chartevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 35 AND 45 AND a.admission_type = 'ACS' AND a.los BETWEEN 1 AND 7 GROUP BY a.hadm_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group ORDER BY a.hadm_id NULLS LAST;